WITH RECURSIVE x18 AS (SELECT x14.v212422 + 1 FROM x19 WHERE x14.v212421 < 200 UNION ALL SELECT 1 + x14.v212421 FROM x20 WHERE x14.v212421 < 100) SELECT x14.v212421, x14.v212421, ST_ASTEXT(ST_ENVELOPE(ST_MPOINTFROMWKB(ST_ASWKB(MULTIPOINT(POINT('0', '0'), POINT('-0', '0'), POINT('0', '-0')))))) AS x4, x14.v212421, SUM(DISTINCT x14.v212421), SUM(DISTINCT SUBSTRING('x', 1, 3)) FROM v212420 AS x14 WHERE x14.v212421 <> '1' GROUP BY x14.v212421, x14.v212421, x14.v212421 WITH ROLLUP ORDER BY x14.v212422